#!/usr/bin/env bash
# PO-07 J1: the application's own security suites against the VERIFIED artifact with its build READ-ONLY.
#   suites.sh <installed app dir> <log dir>
# Each suite runs inside a transient systemd unit (as the runner user) whose mount namespace makes the build — .next
# and node_modules — read-only; every `next start` server the suite spawns inherits it. The rest of the tree (the
# suites' own files, .env for the customer tier) stays writable for the harness. Fictional data only, disposable
# databases on the runner's loopback, TEST-ONLY secrets generated by the suites.
set -Euo pipefail
export LC_ALL=C
APP="$(realpath "${1:?app dir}")"; LOG="$(realpath -m "${2:?log dir}")"; mkdir -p "$LOG"
U="$(id -u)"; G="$(id -g)"
failed=0
ro() { # NAME COMMAND... — one suite with the build read-only
  local name="$1"; shift
  local t0=$SECONDS rc=0
  sudo systemd-run --unit="po07-suite-$name" --uid="$U" --gid="$G" --wait --pipe --quiet --collect \
    -p WorkingDirectory="$APP" -p "ReadOnlyPaths=$APP/.next $APP/node_modules" \
    --setenv=PATH="$PATH" --setenv=HOME="$HOME" --setenv=CI=1 --setenv=NEXT_TELEMETRY_DISABLED=1 \
    --setenv=PLATFORM_TEST_ADMIN_DATABASE_URL="$PLATFORM_TEST_ADMIN_DATABASE_URL" \
    --setenv=PO07_CHROMIUM="$PO07_CHROMIUM" --setenv=PO01B_CHROMIUM="$PO07_CHROMIUM" --setenv=PLAYWRIGHT_CHROMIUM="$PO07_CHROMIUM" --setenv=CHROMIUM_PATH="$PO07_CHROMIUM" \
    ${EXTRA_ENV:+$EXTRA_ENV} -- "$@" < /dev/null > "$LOG/$name.log" 2>&1 || rc=$?
  local line; line="$(grep -aE '[0-9]+ ?/ ?[0-9]+ (checks|suites)|passed|VERIFICATION (PASS|FAIL)' "$LOG/$name.log" | tail -1 | cut -c1-160)"
  printf '%-5s %-44s exit %-3s %4ss  %s\n' "$([ $rc -eq 0 ] && echo PASS || echo FAIL)" "$name" "$rc" "$((SECONDS - t0))" "$line"
  [ $rc -eq 0 ] || { failed=$((failed + 1)); tail -30 "$LOG/$name.log" | sed 's/^/      /'; }
}
TSX=(npx tsx --conditions=react-server)
echo "== platform suites (each spawns next start from the read-only build)"
ro h1-host-binding               "${TSX[@]}" verify/verify-platform-host-binding.mts
ro platform-browser-mfa          "${TSX[@]}" verify/verify-platform-browser.mts
ro platform-auth                 "${TSX[@]}" verify/verify-platform-auth.mts
ro platform-team-sessions        "${TSX[@]}" verify/verify-platform-team-sessions.mts
ro invitation-acceptance-browser "${TSX[@]}" verify/verify-platform-invitation-acceptance-browser.mts
ro user-acceptance-browser       "${TSX[@]}" verify/verify-platform-user-acceptance-browser.mts
echo "== customer tier: PDF generation with Chromium, private storage (one next start on :3000, the read-only build)"
EXTRA_ENV="--setenv=STORAGE_DRIVER=fake --setenv=STORAGE_FAKE_DIR=$RUNNER_TEMP/fake-storage --setenv=CHROMIUM_EXECUTABLE_PATH=$PO07_CHROMIUM --setenv=DATABASE_URL=$CUSTOMER_DATABASE_URL"
for s in verify-pdf-branding verify-print-apply verify-private-storage; do
  ro "customer-${s#verify-}" node --env-file-if-exists=.env verify/run-browser-suites.mjs --skip-build "--only=$s"
done
unset EXTRA_ENV
echo "== the build after every suite"
if (cd "$APP" && sha256sum --quiet --strict -c "$MANIFEST"); then echo "PASS  every build file unchanged ($(wc -l < "$MANIFEST") files)"; else echo "FAIL  build files changed"; failed=$((failed + 1)); fi
echo "SUITES $([ $failed -eq 0 ] && echo PASS || echo FAIL) failed=$failed"
exit $([ $failed -eq 0 ] && echo 0 || echo 1)
